const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  OWNER_EMAIL: s.owner_email,
  OWNER_PHONE: s.owner_phone_e164,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  EMAIL_ALERTS_ENABLED: s.email_alerts_enabled,
  SMS_ALERTS_ENABLED: s.sms_reports_enabled,
  DEFAULT_TIMEZONE: s.timezone,
  STALE_LEADS_SHOWN: s.pipeline_digest_stale_leads_shown
};

const todayStr = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toFormat('yyyy-MM-dd');
const leads = $input.all().map(i => i.json);

const counts = { New: 0, Contacted: 0, Booked: 0, Stale: 0 };
let newToday = 0;
let bookedToday = 0;
const staleLeads = [];

for (const lead of leads) {
  const status = (lead['Status'] || '').trim();
  if (counts[status] !== undefined) counts[status]++;

  const created = String(lead['Date Created'] || '').slice(0, 10);
  if (created === todayStr) newToday++;

  const lastContact = String(lead['Last Contact'] || '').slice(0, 10);
  if (status === 'Booked' && lastContact === todayStr) bookedToday++;

  if (status === 'Stale') {
    staleLeads.push({
      leadId: lead['Lead ID'] || '',
      name: [lead['First Name'], lead['Last Name']].filter(Boolean).join(' ') || 'Unknown',
      phone: lead['Phone'] || ''
    });
  }
}

const dateLabel = DateTime.now().setZone(CONFIG.DEFAULT_TIMEZONE).toFormat("cccc, LLLL d, yyyy");

let smsMessage = 'Daily Pipeline - ' + CONFIG.COMPANY_NAME + '\n';
smsMessage += 'New ' + counts.New + ' | Contacted ' + counts.Contacted + ' | Booked ' + counts.Booked + ' | Stale ' + counts.Stale + '\n';
if (staleLeads.length) {
  smsMessage += '\nStale leads needing a personal touch:\n';
  staleLeads.slice(0, CONFIG.STALE_LEADS_SHOWN).forEach(l => {
    smsMessage += l.leadId + ' ' + l.name + ' ' + l.phone + '\n';
  });
  if (staleLeads.length > CONFIG.STALE_LEADS_SHOWN) smsMessage += '+' + (staleLeads.length - CONFIG.STALE_LEADS_SHOWN) + ' more\n';
}
smsMessage += '\nToday: ' + newToday + ' new, ' + bookedToday + ' booked';
smsMessage = smsMessage.trim();

const emailSubject = CONFIG.COMPANY_NAME + ' - Daily Pipeline Digest (' + dateLabel + ')';

const countRows = [
  ['New', counts.New],
  ['Contacted', counts.Contacted],
  ['Booked', counts.Booked],
  ['Stale', counts.Stale]
].map(([label, value]) =>
  '<tr><td style="padding:6px 12px 6px 0;font-weight:bold;color:#374151;">' + label + '</td><td style="padding:6px 0;color:#111827;">' + value + '</td></tr>'
).join('');

let staleHtml = '<p style="color:#6b7280;">No stale leads need attention today.</p>';
if (staleLeads.length) {
  const rows = staleLeads.map(l =>
    '<tr><td style="padding:6px 12px 6px 0;color:#111827;">' + l.leadId + '</td><td style="padding:6px 12px 6px 0;color:#111827;">' + l.name + '</td><td style="padding:6px 0;color:#111827;">' + l.phone + '</td></tr>'
  ).join('');
  staleHtml = '<table style="width:100%;border-collapse:collapse;margin-top:8px;">' + rows + '</table>';
}

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;">' +
  '<h2 style="color:#111827;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">Daily Pipeline Digest</h2>' +
  '<p style="color:#6b7280;margin-top:0;">' + dateLabel + '</p>' +
  '<table style="width:100%;border-collapse:collapse;margin-top:12px;">' + countRows + '</table>' +
  '<h3 style="margin-top:24px;color:#111827;">Stale Leads Needing a Personal Touch</h3>' +
  staleHtml +
  '<p style="margin-top:20px;color:#374151;">Today: ' + newToday + ' new lead' + (newToday === 1 ? '' : 's') + ', ' + bookedToday + ' booked.</p>' +
  '<p style="color:#6b7280;font-size:12px;margin-top:24px;">Sent automatically by ' + CONFIG.COMPANY_NAME + '.</p>' +
  '</div>';

return [{ json: {
  emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
  smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
  ownerEmail: CONFIG.OWNER_EMAIL,
  ownerPhone: CONFIG.OWNER_PHONE,
  twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
  emailSubject,
  emailHtml,
  smsMessage,
  counts,
  newToday,
  bookedToday,
  staleCount: staleLeads.length
} }];
